import numpy as np
def stl_volume(path):
    v=[]; 
    for line in open(path):
        if line.strip().startswith("vertex"): v.append([float(x) for x in line.split()[1:]])
    v=np.array(v).reshape(-1,3,3)
    return np.abs(np.einsum('ij,ij->i', v[:,0], np.cross(v[:,1],v[:,2])).sum()/6.0)
